import { I, dish } from "./catalog-kit.ts";
import type { Recipe, RecipeSource } from "./types";

const packSource: RecipeSource = {
  book: "Troop Cookbook 2023",
  author: "Dennis Schmitt / Troop 928 (Houston, TX)",
  year: 2023,
  era: "2020s",
  archiveId: "troop-cookbook-2023",
  credit: "Troop Cookbook 2023 (Dennis Schmitt / Troop 928, Houston TX). Internet Archive troop-cookbook-2023. Founder-cleared free use.",
};

function h(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  nutrition: Recipe["nutrition"],
): Recipe {
  return dish({
    id, name, cuisine, description, minutes, protein, plate,
    tags: Array.from(new Set(["vintage", "book-troop-2023", "era-2020s", ...tags])),
    ingredients, steps, nutrition, source: packSource,
  });
}

